existing_tables = set(tables['name'].tolist())
candidates = [s for s in etfs['Symbol'].tolist() if s in existing_tables]
print(len(candidates), 'candidates with trade tables')

qualifying = []
for sym in candidates:
    try:
        r = conn_trade.execute(
            f'SELECT MAX("Adj Close") FROM "{sym}" WHERE Date >= \'2015-01-01\' AND Date <= \'2015-12-31\''
        ).fetchone()
        if r and r[0] is not None and r[0] > 200:
            qualifying.append((sym, r[0]))
    except Exception as e:
        print(sym, e)

print(len(qualifying))
qualifying_sorted = sorted(qualifying, key=lambda x: x[0])
for q in qualifying_sorted:
    print(q)
